const provided = (msg.req && msg.req.headers && msg.req.headers.authorization) || '';
const user = env.get('DATABASUS_WEBHOOK_USER') || '';
const pass = env.get('DATABASUS_WEBHOOK_PASS') || '';

if (!user && !pass) {
    // No credentials configured on the relay side - skip the check.
    // Set DATABASUS_WEBHOOK_USER / DATABASUS_WEBHOOK_PASS to enable it.
    return [msg, null];
}

const expected = 'Basic ' + Buffer.from(user + ':' + pass).toString('base64');

if (provided === expected) {
    return [msg, null];
}

msg.statusCode = 401;
msg.headers = { 'WWW-Authenticate': 'Basic realm="databasus"' };
msg.payload = 'Unauthorized';
return [null, msg];

const body = msg.payload || {};

// Confirmed real Databasus webhook shape: { "heading": "...", "message": "..." }
const heading = body.heading || '';
const message = body.message || heading || '(no message)';
const time = new Date().toISOString();

const text = (heading && heading !== message ? '**' + heading + '**\n' : '') + message + '\n_relayed ' + time + '_';

// ---- Build the signed Nextcloud Talk Bot API request ----
const crypto = global.get('crypto');
const ncUrl = env.get('NC_URL');
const ncToken = env.get('NC_TOKEN');
const ncSecret = env.get('NC_BOT_SECRET');

const talkBody = JSON.stringify({ message: text });
const random = crypto.randomBytes(32).toString('hex');
const signature = crypto.createHmac('sha256', ncSecret).update(random + talkBody).digest('hex');

msg.url = ncUrl + '/ocs/v2.php/apps/spreed/api/v1/bot/' + ncToken + '/message';
msg.method = 'POST';
msg.headers = {
    'Content-Type': 'application/json',
    'Accept': 'application/json',
    'OCS-APIRequest': 'true',
    'X-Nextcloud-Talk-Bot-Random': random,
    'X-Nextcloud-Talk-Bot-Signature': signature
};
msg.payload = talkBody;

return msg;
